export function isDungeonAccessible(dungeonId: string, currentTime: Date): boolean {
    const resetTime = new Date(currentTime);
    resetTime.setHours(3, 0, 0, 0);
    return currentTime > resetTime;
}

// Examples as asserts
// assert isDungeonAccessible("Catacombs", new Date(2023, 9, 5, 2, 59)) === false;
// assert isDungeonAccessible("VolcanoCave", new Date(2023, 9, 5, 3, 1)) === true;

type Position = [number, number];

function shortestSafePath(dungeon: string[][]): number {
    if (!dungeon || !dungeon.length || !dungeon[0].length) {
        return -1;
    }

    const rows = dungeon.length;
    const cols = dungeon[0].length;
    let startRow = -1;
    let startCol = -1;
    let exitRow = -1;
    let exitCol = -1;

    // Find start and exit positions
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            if (dungeon[i][j] === 'S') {
                startRow = i;
                startCol = j;
            } else if (dungeon[i][j] === 'E') {
                exitRow = i;
                exitCol = j;
            }
        }
    }

    // If start or exit not found, return -1
    if (startRow === -1 || exitRow === -1) {
        return -1;
    }

    // Directions: up, down, left, right
    const directions: Position[] = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    // Use two-pointer BFS approach: currentLevel and nextLevel
    // currentLevel: positions at current distance
    // nextLevel: positions to be processed in next step
    let currentLevel: Position[] = [[startRow, startCol]];
    const visited = new Set<string>();
    visited.add(`${startRow},${startCol}`);
    let steps = 0;

    while (currentLevel.length > 0) {
        const nextLevel: Position[] = [];

        for (const [row, col] of currentLevel) {
            // Check if reached exit
            if (row === exitRow && col === exitCol) {
                return steps;
            }

            // Explore neighbors
            for (const [dr, dc] of directions) {
                const newRow = row + dr;
                const newCol = col + dc;

                // Check bounds and if tile is safe and not visited
                if (
                    newRow >= 0 &&
                    newRow < rows &&
                    newCol >= 0 &&
                    newCol < cols &&
                    dungeon[newRow][newCol] === '.' &&
                    !visited.has(`${newRow},${newCol}`)
                ) {
                    visited.add(`${newRow},${newCol}`);
                    nextLevel.push([newRow, newCol]);
                }
            }
        }

        currentLevel = nextLevel;
        steps++;
    }

    return -1;
}

export { shortestSafePath };

