def parseInventory(log: str) -> dict[str, dict[str, str | int]]:
    """
    Parse a multiline inventory log into a dictionary of items with their quantity and location.
    Each line is formatted as "ITEM:QTY:LOCATION".
    """
    result = {}
    for line in log.strip().splitlines():
        item, qty, location = line.split(":")
        result[item] = {"qty": int(qty), "location": location}
    return result

# Example tests
assert parseInventory("Oxygen:12:Module A\nWater:5:Module B") == {
    "Oxygen": {"qty": 12, "location": "Module A"},
    "Water": {"qty": 5, "location": "Module B"}
}
assert parseInventory("Tool:3:Lab 2\nBattery:20:Hangar") == {
    "Tool": {"qty": 3, "location": "Lab 2"},
    "Battery": {"qty": 20, "location": "Hangar"}
}

