export function parseInventory(log: string): Record<string, { qty: number; location: string }> {
  const result: Record<string, { qty: number; location: string }> = {};
  for (const line of log.trim().split('\n')) {
    const [item, qty, location] = line.split(':');
    result[item] = { qty: parseInt(qty, 10), location };
  }
  return result;
}

export function minimizeDeliveryTime(pizzas: Array<[number, number]>, maxDistance: number): number {
    let minDeliveries = Infinity;
    let left = 0;

    for (let right = 0; right < pizzas.length; right++) {
        // Expand window to include current pizza
        // Check if current pizza is within maxDistance
        while (pizzas[right][1] > maxDistance) {
            right++;
            if (right >= pizzas.length) {
                break;
            }
        }

        // Shrink window from left while maintaining constraint
        while (left <= right && pizzas[left][1] > maxDistance) {
            left++;
        }

        // If current window is valid, update minimum
        if (left <= right) {
            minDeliveries = Math.min(minDeliveries, right - left + 1);
        }
    }

    return minDeliveries !== Infinity ? minDeliveries : 0;
}

export function balanceInventory(supplies: number[], orders: number[]): number {
    let i = 0;
    let j = 0;
    let fulfilled = 0;

    while (i < supplies.length && j < orders.length) {
        if (supplies[i] >= orders[j]) {
            fulfilled++;
            j++;
        }
        i++;
    }

    return fulfilled;
}

interface Song {
  title: string;
  artist: string;
  mood: string;
}

function shufflePlaylist(songs: Song[], seed: number): Song[] {
  // Set the seed for consistent random behavior
  const random = new Random(seed);

  // Sort by mood (ascending), then by artist (alphabetically), then by title (reverse alphabetical)
  const sortedSongs = [...songs].sort((a, b) => {
    if (a.mood !== b.mood) return a.mood.localeCompare(b.mood);
    if (a.artist !== b.artist) return a.artist.localeCompare(b.artist);
    // Reverse alphabetical by first letter of title
    const aFirstChar = a.title.length > 0 ? a.title[0].toUpperCase() : '';
    const bFirstChar = b.title.length > 0 ? b.title[0].toUpperCase() : '';
    return bFirstChar.localeCompare(aFirstChar);
  });

  // Group by mood and artist
  const groups: Map<string, Song[]> = new Map();
  for (const song of sortedSongs) {
    const key = `${song.mood}|${song.artist}`;
    if (!groups.has(key)) {
      groups.set(key, []);
    }
    groups.get(key)!.push(song);
  }

  // Shuffle each group using the seed
  const shuffledSongs: Song[] = [];
  const sortedKeys = Array.from(groups.keys()).sort();

  for (const key of sortedKeys) {
    const group = groups.get(key)!;
    // Shuffle the group using the seeded random
    for (let i = group.length - 1; i > 0; i--) {
      const j = random.nextInt(i + 1);
      [group[i], group[j]] = [group[j], group[i]];
    }
    shuffledSongs.push(...group);
  }

  return shuffledSongs;
}

// Simple seeded random number generator
class Random {
  private seed: number;

  constructor(seed: number) {
    this.seed = seed;
  }

  private next(): number {
    this.seed = (this.seed * 9301 + 49297) % 233280;
    return this.seed / 233280;
  }

  public nextInt(max: number): number {
    return Math.floor(this.next() * max);
  }
}

